export type ParsedBindInstruction<
  TProgram extends string = typeof CONTAINMENT_HOOK_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** The mint's mint authority: only the launcher can bind a mint. */
    mintAuthority: TAccountMetas[0];
    /** Pays the rent of the config and the validation account. */
    payer: TAccountMetas[1];
    /** The mint to contain. */
    mint: TAccountMetas[2];
    /** Created here, so a second `bind` of the same mint fails. */
    config: TAccountMetas[3];
    /** The validation account, created here and written by the handler. */
    extraAccountMetas: TAccountMetas[4];
    /** The unlock PDA, which must be the mint's transfer hook authority; it holds no data. */
    unlock: TAccountMetas[5];
    /** The home market: the router's `Market` account. */
    market: TAccountMetas[6];
    /** The tax AMM market state the `Market` records. */
    marketState: TAccountMetas[7];
    systemProgram: TAccountMetas[8];
  };
  data: BindInstructionData;
};

export function parseBindInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedBindInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      mintAuthority: getNextAccount(),
      payer: getNextAccount(),
      mint: getNextAccount(),
      config: getNextAccount(),
      extraAccountMetas: getNextAccount(),
      unlock: getNextAccount(),
      market: getNextAccount(),
      marketState: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getBindInstructionDataDecoder().decode(instruction.data),
  };
}
